{"content":"//! `murmur` - murmurhash command line utility
//!
//! copyright (c) 2014-2025 joseph werle <joseph.werle@gmail.com>

use std::io::{self, BufRead, Write};

use murmurhash::{murmurhash, VERSION};

fn usage() {
    eprintln!("usage: murmur [-hV] [options]");
}

fn help() {
    eprintln!("\noptions:");
    eprintln!("\n  --seed=[seed]  hash seed (optional)");
    eprintln!("\n");
}

fn main() {
    let mut seed: Option<u32> = None;

    // parse opts
    for opt in std::env::args().skip(1) {
        if let Some(short) = opt.strip_prefix('-').filter(|_| opt.len() == 2) {
            match short {
                'h' => {
                    usage();
                    help();
                    return;
                }
                'V' => {
                    eprintln!("{}", VERSION);
                    return;
                }
                _ => {
                    eprintln!("unknown option: `-{}'", short);
                    usage();
                    std::process::exit(1);
                }
            }
        } else if let Some(long) = opt.strip_prefix("--") {
            if let Some(value) = long.strip_prefix("seed=") {
                match value.parse::<u32>() {
                    Ok(v) => seed = Some(v),
                    Err(_) => {
                        eprintln!("invalid seed: `{value}'");
                        usage();
                        std::process::exit(1);
                    }
                }
            } else {
                eprintln!("unknown option: `--{long}'");
                usage();
                std::process::exit(1);
            }
        } else {
            eprintln!("unknown option: `{opt}'");
            usage();
            std::process::exit(1);
        }
    }

    let seed = seed.unwrap_or(0);

    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();

    // read lines from stdin and hash each one
    for line in stdin.lock().lines() {
        match line {
            Ok(line) => {
                let key = line.trim_end_matches(['\n', '\r']);
                let h = murmurhash(key.as_bytes(), seed);
                let _ = writeln!(out, "{}", h);
            }
            Err(_) => break,
        }
    }
}
