        // flags
        if let Some(rest) = opt.strip_prefix('-') {
            match rest {
                "h" => {
                    usage();
                    help();
                    return;
                }

                "V" => {
                    eprintln!("{VERSION}");
                    return;
                }

                r if r.starts_with('-') => {
                    let r = &r[1..];
                    if let Some(s) = r.strip_prefix("seed") {
                        if let Some(v) = s.strip_prefix('=') {
                            match v.parse::<u32>() {
                                Ok(n) => seed = Some(n),
