    let seed = seed.unwrap_or(0);

    let stdin = io::stdin();

    if stdin.is_terminal() {
        process::exit(1);
    }

    let mut lines = stdin.lock().lines();
    let mut first = true;

    while let Some(line) = lines.next() {
        match line {
